#include <WiFi.h>
#include <WebSocketsServer.h>
WebSocketsServer ws({{port}});

void onEvent(uint8_t num, WStype_t type, uint8_t* p, size_t len) {
  if (type == WStype_TEXT) ws.sendTXT(num, p, len);
}

void setup() {
  WiFi.begin("{{ssid}}", "{{password}}");
  while (WiFi.status() != WL_CONNECTED) delay(300);
  ws.begin();
  ws.onEvent(onEvent);
}

void loop() { ws.loop(); }
